<script setup lang="ts">
import {computed} from 'vue'
const props=defineProps<{item:any,stored?:boolean,expanded?:boolean}>()
const quality=computed(()=>({普通:'normal',高级:'advanced',稀有:'rare',神器:'unique',史诗:'epic',勇者:'chronicle',传说:'legendary'} as Record<string,string>)[props.item.rarity_name]||'unknown')
const policy=computed(()=>props.item.policy_state==='verified'?'已验证':props.item.policy_state==='blocked'?'不可发放':props.item.policy_state==='trial'||props.item.sendable||props.item.allowed?'允许试发，未验证':'不可发放')
</script>
<template><div class="item-quick-facts" :class="'rarity-'+quality"><strong class="item-quick-name">{{item.name||'名称未收录'}}<span v-if="stored&&item.enhancement"> +{{item.enhancement}}</span></strong><span class="item-quick-subtitle">{{item.rarity_name||'品级未收录'}} · {{item.part_name||item.type_name||'物品'}} · {{item.level==null?'等级未知':'Lv. '+item.level}}</span><span v-if="item.usable_jobs?.length">{{item.usable_jobs.map((job:any)=>job.name).join(' / ')}}</span><span v-if="item.set_id">{{item.set_name||'套装 #'+item.set_id}}</span><dl v-if="item.base_attributes?.length"><div v-for="attribute in item.base_attributes.slice(0,6)" :key="attribute.tag"><dt>{{attribute.label}}</dt><dd>{{attribute.values.join(' / ')}}</dd></div></dl><span v-if="stored&&item.enchantment?.summary">附魔：{{item.enchantment.summary}}</span><span v-if="!stored" class="item-quick-policy">{{policy}}<template v-if="item.policy_reason"> · {{item.policy_reason}}</template></span><small>{{stored?'存档属性':'PVF 已知属性'}} · #{{item.id}}<template v-if="!expanded"> · 点击查看完整详情</template></small></div></template>
<style scoped>
.item-quick-facts{display:grid;gap:8px;padding:16px;width:300px;max-width:calc(100vw - 40px);border:1px solid #6e675a;border-radius:9px;background:#232624;color:#ece7de;box-shadow:0 12px 32px #0004;font-size:12px;line-height:1.55;text-align:left}.item-quick-name{font-size:16px;color:var(--rarity-color,#ece7de)}.item-quick-subtitle{color:#c9c2b5}.item-quick-facts dl{margin:3px 0;border-block:1px solid #ffffff20;padding-block:8px}.item-quick-facts dl>div{display:flex;justify-content:space-between;gap:12px;padding:2px 0}.item-quick-facts dd{margin:0;color:#ded6bb}.item-quick-facts small{color:#a8a99e;font-size:10px}.item-quick-policy{color:#cbb996}.rarity-normal{--rarity-color:#e9e6df}.rarity-advanced{--rarity-color:#91b8e7}.rarity-rare{--rarity-color:#bd9ae6}.rarity-unique{--rarity-color:#e59ab8}.rarity-epic{--rarity-color:#ead083}.rarity-chronicle{--rarity-color:#d0b28c}.rarity-legendary{--rarity-color:#e8aa78}
</style>
